#include <Arduino.h>
#include <Servo.h>
Servo servo1;
Servo servo2;

void setup();
void loop();
void setup() {
  servo1.attach(8);  
  servo2.attach(9);  
  for (int pin = 2; pin <= 5; pin++) {  
    pinMode(pin, OUTPUT);
  }
  for (int pin = 10; pin <= 13; pin++) {  
    pinMode(pin, OUTPUT);
  }
  pinMode(44, OUTPUT);  
  pinMode(45, OUTPUT);  
}
void loop() {
  static int angle = 0;
  servo1.write(angle);
  servo2.write(angle);
  analogWrite(2, 255);  
  analogWrite(3, 0);    
  analogWrite(4, 0);    
  if (angle > 90){
    analogWrite(5, 0);  
    analogWrite(6, 0);    
    analogWrite(7, 255);    
  }else{
    analogWrite(5, 0);    
    analogWrite(6, 0);    
    analogWrite(7, 0);    
  }
  int litLEDs = angle / 30;
  int pins[] = {10, 11, 12, 13, 44, 45};
  for (int i = 0; i < 6; i++) {
      digitalWrite(pins[i], (i < litLEDs) ? HIGH : LOW);
  }
  delay(2000);
  angle = (angle >= 180) ? 0 : angle + 30;
}
